// Phase 2: block content (depth 1) + OKF-lite fields (title/slug/folder/summary).
// folder='' for now -- flat structure chosen 2026-07-14 (no Notion select property exists yet for
// categorization). Populate folder from a select property later to activate OKF subfolders --
// downstream nodes (Upsert & Diff PG, Build Write Script, Build Indexes) already support non-empty folder.
// Pure-JS FNV-1a hash instead of require('crypto') -- n8n's Code node sandbox blocks Node built-ins.
// Only depth-1 blocks are converted; >100 blocks/page or nested children get a placeholder link back
// to the Notion original instead of full recursive fetch (see n8n/README.md Phase 2 notes) --
// this intentionally skips the HTTP node's built-in cursor pagination to avoid the same kind of
// fragile-toggle/fan-out issues documented for other advanced n8n UI options in this environment.
function fnv1aHash(str) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function slugify(t) {
  const s = String(t || 'untitled')
    .normalize('NFKC')
    .replace(/[\\/:*?"<>|#^\[\]{}.]/g, ' ')
    .trim()
    .replace(/\s+/g, '-')
    .slice(0, 80)
    .replace(/^-+|-+$/g, '');
  return s || 'untitled';
}

function richTextToMd(rt) {
  if (!Array.isArray(rt)) return '';
  return rt.map((t) => {
    let text = t.plain_text || '';
    const ann = t.annotations || {};
    if (ann.code) text = '`' + text + '`';
    if (ann.bold) text = `**${text}**`;
    if (ann.italic) text = `*${text}*`;
    if (ann.strikethrough) text = `~~${text}~~`;
    if (t.href) text = `[${text}](${t.href})`;
    return text;
  }).join('');
}

function blockToMd(b) {
  const type = b.type;
  const data = b[type] || {};
  const text = richTextToMd(data.rich_text);
  let line;
  switch (type) {
    case 'paragraph': line = text; break;
    case 'heading_1': line = `# ${text}`; break;
    case 'heading_2': line = `## ${text}`; break;
    case 'heading_3': line = `### ${text}`; break;
    case 'bulleted_list_item': line = `- ${text}`; break;
    case 'numbered_list_item': line = `1. ${text}`; break;
    case 'to_do': line = `- [${data.checked ? 'x' : ' '}] ${text}`; break;
    case 'quote': line = `> ${text}`; break;
    case 'callout': line = `> ${text}`; break;
    case 'code': line = '```' + (data.language || '') + '\n' + text + '\n```'; break;
    case 'divider': line = '---'; break;
    case 'image': {
      const url = (data.file && data.file.url) || (data.external && data.external.url) || '';
      line = `![image](${url})`;
      break;
    }
    case 'bookmark': line = `[${data.url || ''}](${data.url || ''})`; break;
    default: line = null;
  }
  if (line === null) return null;
  const listTypes = ['bulleted_list_item', 'numbered_list_item', 'to_do'];
  if (b.has_children && !listTypes.includes(type)) {
    line += `  \n> (하위 블록 있음 — Notion 원본 참조: https://notion.so/${String(b.id || '').replace(/-/g, '')})`;
  }
  return line;
}

const pageItems = $('Get Notion Pages').all();
const blockItems = $input.all();

// Fetch Blocks runs once per page (1 HTTP request = 1 item -- no pagination fan-out, see comment above).
// Correlate each blocks-response back to its source page via pairedItem rather than array index,
// since that's the robust way n8n tracks item lineage across a 1:1 node.
const blocksByPageIndex = {};
const truncatedByPageIndex = {};
for (const item of blockItems) {
  const idx = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : 0;
  blocksByPageIndex[idx] = (item.json && item.json.results) || [];
  truncatedByPageIndex[idx] = !!(item.json && item.json.has_more);
}

const out = [];
for (let i = 0; i < pageItems.length; i++) {
  const j = pageItems[i].json;
  const title = j.name || j.title || j.id;
  const slug = slugify(title);
  const props = j.properties || {};
  const tags = [];
  for (const v of Object.values(props)) {
    if (v && v.type === 'multi_select' && Array.isArray(v.multi_select)) {
      for (const t of v.multi_select) tags.push(t.name);
    }
  }
  const updated = j.last_edited_time || '';
  const blocks = blocksByPageIndex[i] || [];
  const bodyLines = blocks.map(blockToMd).filter((l) => l !== null);
  if (truncatedByPageIndex[i]) {
    bodyLines.push(`> (100블록 초과 — 나머지는 Notion 원본 참조: ${j.url || j.id})`);
  }
  const body = bodyLines.join('\n\n');
  const firstParagraph = blocks.find((b) => b.type === 'paragraph' && (b.paragraph.rich_text || []).length);
  const summary = firstParagraph ? richTextToMd(firstParagraph.paragraph.rich_text).slice(0, 120) : '';
  const folder = ''; // flat structure (2026-07-14) -- set from a Notion select property later to enable OKF subfolders

  const lines = [
    '---',
    `title: "${String(title).replace(/"/g, "'")}"`,
    `notion_id: ${j.id}`,
    `url: ${j.url || ''}`,
    `tags: [${tags.map((t) => `"${t}"`).join(', ')}]`,
    `summary: "${summary.replace(/"/g, "'")}"`,
    `updated: ${updated}`,
    '---',
    '',
    `# ${title}`,
    '',
    `> Notion 원본: ${j.url || j.id}`,
    '',
    body
  ];
  const content = lines.join('\n');
  const hash = fnv1aHash(content);
  out.push({ json: { page_id: j.id, title, slug, folder, summary, content, hash, last_edited: updated } });
}
return out;

// proot + Android FUSE storage: n8n's readWriteFile node fails to create files there (ENOENT)
// even though plain shell redirection works. Also: this node's downstream Execute Command node's
// per-item execution depends on an 'Execute Once' toggle that repeatedly reverted in the n8n UI on
// Tab S9 -- so instead of one shell call per item, emit ONE combined script covering every item and
// run it once. That makes the toggle's state irrelevant either way.
// Postgres node emits a pass-through item even when RETURNING matched 0 rows (unchanged page) --
// skip those instead of erroring, since "nothing to write" is the correct outcome for them.
const inputItems = $input.all();
const lines = [
  'set -e',
  'VAULT="REPLACE_ME_VAULT_PATH"',
  'mkdir -p "$VAULT/_notion-sync"'
];
let count = 0;
for (const item of inputItems) {
  const j = item.json;
  if (!j.content) continue;
  const b64 = Buffer.from(j.content, 'utf8').toString('base64');
  const dir = j.folder ? `$VAULT/_notion-sync/${j.folder}` : '$VAULT/_notion-sync';
  if (j.folder) lines.push(`mkdir -p "${dir}"`);
  lines.push(`echo '${b64}' | base64 -d > "${dir}/${j.slug}.md"`);
  count++;
}
const script = lines.join('\n');
return [{ json: { script, filesWritten: count } }];

// Index Query (PG) has no per-item parameters, so if N changed pages flowed into this branch it runs
// N times with the identical full-table query -- deliberately not relying on n8n's 'Execute Once' node
// toggle here (it was flaky/reverted during Phase 1 debugging, see n8n/README.md #4). Dedupe by page_id
// instead so repeated identical batches are harmless.
const seen = new Map();
for (const item of $input.all()) {
  const j = item.json;
  if (j && j.page_id) seen.set(j.page_id, j);
}
const rows = [...seen.values()];

const byFolder = {};
for (const r of rows) {
  const folder = r.folder || '';
  if (!byFolder[folder]) byFolder[folder] = [];
  byFolder[folder].push(r);
}

const lines = ['---', 'title: "_notion-sync index"', `generated: ${new Date().toISOString()}`, '---', '', '# Notion Sync Index', ''];
const folders = Object.keys(byFolder).sort();
for (const folder of folders) {
  if (folder) lines.push(`## ${folder}`, '');
  const sorted = byFolder[folder].sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  for (const r of sorted) {
    const summary = r.summary ? ` — ${r.summary}` : '';
    lines.push(`- [[${r.slug}]]${summary}`);
  }
  lines.push('');
}
const content = lines.join('\n');
const b64 = Buffer.from(content, 'utf8').toString('base64');
const script = [
  'set -e',
  'VAULT="REPLACE_ME_VAULT_PATH"',
  'mkdir -p "$VAULT/_notion-sync"',
  `echo '${b64}' | base64 -d > "$VAULT/_notion-sync/index.md"`
].join('\n');
return [{ json: { script } }];
